-- Isolated fixtures only; all records roll back before baseline security tests.
begin;
create function pg_temp.scanner_assert(ok boolean,label text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL scanner: %',label;end if;end$$;
insert into auth.users(id,email,email_confirmed_at,is_anonymous)values('c3400000-0000-4000-8000-000000000001','scanner-one@example.invalid',now(),false),('c3400000-0000-4000-8000-000000000002','scanner-two@example.invalid',now(),false),('c3400000-0000-4000-8000-000000000003','scanner-admin@example.invalid',now(),false);
insert into auth.sessions(id,user_id,aal)values('c3400000-0000-4000-9000-000000000003','c3400000-0000-4000-8000-000000000003','aal2');
insert into auth.mfa_factors(user_id,status)values('c3400000-0000-4000-8000-000000000003','verified');
insert into e34_private.staff_roles(user_id,role)values('c3400000-0000-4000-8000-000000000003','admin');
select set_config('request.jwt.claims','{"sub":"c3400000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
set local role authenticated;
insert into public.owned_vehicles(id,nickname,model_id,configuration)values('c3400000-0000-4000-9000-000000000001','Scanner fixture','525i','{"model":"525i","engine":"M50TU","year":"1995","market":"US"}');
insert into public.vehicle_configuration_evidence(id,vehicle_id,attribute,value,kind,source)values('c3400000-0000-4000-8000-000000000011','c3400000-0000-4000-9000-000000000001','engine','M50TU','factory','Synthetic factory document fixture'),('c3400000-0000-4000-8000-000000000012','c3400000-0000-4000-9000-000000000001','engine','M60','modified','Synthetic modification observation');
select public.save_vehicle_configuration('c3400000-0000-4000-9000-000000000001',0,'{"engine":"c3400000-0000-4000-8000-000000000012"}');
select pg_temp.scanner_assert((select configuration->>'engine'='M60'from public.owned_vehicles limit 1),'installed engine resolved without destroying factory evidence');
select pg_temp.scanner_assert((select count(*)=2 from public.vehicle_configuration_evidence),'factory evidence retained');
do $$begin begin perform public.save_vehicle_configuration('c3400000-0000-4000-9000-000000000001',0,'{}');raise exception 'FAIL stale configuration accepted';exception when raise_exception then if sqlerrm='FAIL stale configuration accepted'then raise;end if;end;end$$;
select pg_temp.scanner_assert(not has_table_privilege('authenticated','public.vehicle_configuration_evidence','UPDATE'),'source evidence cannot be overwritten');
select pg_temp.scanner_assert(not has_table_privilege('authenticated','public.vehicle_configuration_revisions','INSERT'),'snapshots cannot be forged by direct inserts');
-- Anonymous and ordinary members cannot unlock visual models or staff review.
select pg_temp.scanner_assert(not(public.scanner_runtime_config()->>'visual_available')::boolean,'visual identification remains gated');
do $$begin begin perform public.scanner_correction_queue();raise exception 'FAIL member accessed review queue';exception when insufficient_privilege then null;end;end$$;
-- A visually reviewed candidate can be saved privately to a garage without inventing an OEM number.
insert into public.component_observations(id,vehicle_id,mode,status,evidence,notes)values('c3400000-0000-4000-8000-000000000099','c3400000-0000-4000-9000-000000000001','loose','candidate','{"candidate_nodes":["family:center-support-bearing"],"method":"owner-selected-visual-candidate","timings":{"views":2}}','Synthetic local candidate-save fixture');
select pg_temp.scanner_assert((select status='candidate'and part_id is null and node_id is null and evidence->'candidate_nodes'->>0='family:center-support-bearing' from public.component_observations where id='c3400000-0000-4000-8000-000000000099'),'candidate saved to garage without asserted OEM identity');
select set_config('request.jwt.claims','{"sub":"c3400000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select pg_temp.scanner_assert((select count(*)=0 from public.component_observations where id='c3400000-0000-4000-8000-000000000099'),'candidate hidden from another member');
select set_config('request.jwt.claims','{"sub":"c3400000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
delete from public.component_observations where id='c3400000-0000-4000-8000-000000000099';
insert into public.component_observations(id,vehicle_id,mode,part_id,node_id,status,evidence)values('c3400000-0000-4000-8000-000000000021','c3400000-0000-4000-9000-000000000001','installed','coolant-pump','m50:water-pump','owner_confirmed','{"markings":["11517527799"],"method":"owner-confirmed-marking"}');
insert into public.scanner_corrections(observation_id,reason)values('c3400000-0000-4000-8000-000000000021','Synthetic correction evidence requires review.');
do $$begin begin insert into public.component_observations(mode,evidence)values('loose','{"photograph":"private pixels"}');raise exception 'FAIL image payload accepted';exception when raise_exception then if sqlerrm='FAIL image payload accepted'then raise;end if;end;end$$;
-- One saved scan continues through the canonical catalog and written checklist, then into the interactive plan.
insert into public.owned_vehicles(id,nickname,model_id,configuration)values('c3400000-0000-4000-9000-000000000002','Second private fixture','530i','{"model":"530i","year":"1994","body":"Touring","transmission":"Automatic"}');
insert into public.guide_progress(id,vehicle_id,guide_id,revision,completed_steps,scan_id,configuration_revision)values('c3400000-0000-4000-8000-000000000031','c3400000-0000-4000-9000-000000000001','m50-water-pump-job-planning','5c458d5b100cc7b4c5c2b469',array[0],'c3400000-0000-4000-8000-000000000021',(select id from public.vehicle_configuration_revisions order by revision desc limit 1));
select pg_temp.scanner_assert((select o.part_id='coolant-pump' and g.configuration_revision is not null from public.guide_progress g join public.component_observations o on o.id=g.scan_id where g.id='c3400000-0000-4000-8000-000000000031'),'written progress retains canonical scan and configuration');
do $$begin begin insert into public.guide_progress(vehicle_id,guide_id,revision,scan_id)values('c3400000-0000-4000-9000-000000000002','m50-water-pump-job-planning','5c458d5b100cc7b4c5c2b469','c3400000-0000-4000-8000-000000000021');raise exception 'FAIL scan linked to a different owned car';exception when foreign_key_violation then null;end;end$$;
update public.guide_progress set repair_plan_id='m50-coolant-pump-r1',operation_ids=array['identify']where id='c3400000-0000-4000-8000-000000000031';
select pg_temp.scanner_assert((select scan_id='c3400000-0000-4000-8000-000000000021' and configuration_revision is not null from public.guide_progress where id='c3400000-0000-4000-8000-000000000031'),'interactive plan reuses the same progress and pinned identification');
do $$begin begin update public.guide_progress set operation_ids=array['pump']where id='c3400000-0000-4000-8000-000000000031';raise exception 'FAIL skipped prerequisites';exception when raise_exception then if sqlerrm='FAIL skipped prerequisites'then raise;end if;end;end$$;
reset role;
select set_config('request.jwt.claims','{"sub":"c3400000-0000-4000-8000-000000000003","session_id":"c3400000-0000-4000-9000-000000000003","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select pg_temp.scanner_assert((public.scanner_runtime_config()->>'visual_available')::boolean,'live MFA administrator can test visual recognition');
select pg_temp.scanner_assert(not(public.scanner_correction_queue()->0?'user_id'),'review queue excludes member identity');
select public.review_scanner_correction((public.scanner_correction_queue()->0->>'id')::uuid,'needs_evidence','Synthetic review requires additional component evidence.');
select pg_temp.scanner_assert(public.scanner_correction_queue()->0->>'decision'='needs_evidence','staff review persists without canonical mutation');
reset role;
update auth.mfa_factors set status='unverified'where user_id='c3400000-0000-4000-8000-000000000003';
set local role authenticated;
select pg_temp.scanner_assert(not(public.scanner_runtime_config()->>'visual_available')::boolean,'revoked factor closes staff testing');
-- Switch to another real synthetic identity: no cross-account reads, links or writes.
reset role;
select set_config('request.jwt.claims','{"sub":"c3400000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
set local role authenticated;
select pg_temp.scanner_assert((select count(*)=0 from public.vehicle_configuration_evidence),'evidence private');
select pg_temp.scanner_assert((select count(*)=0 from public.component_observations),'scan history private');
insert into public.owned_vehicles(id,nickname,model_id)values('c3400000-0000-4000-9000-000000000022','Other owner fixture','525i');
do $$begin begin insert into public.guide_progress(vehicle_id,guide_id,revision,scan_id)values('c3400000-0000-4000-9000-000000000022','m50-water-pump-job-planning','5c458d5b100cc7b4c5c2b469','c3400000-0000-4000-8000-000000000021');raise exception 'FAIL other owner scan linked into a repair';exception when foreign_key_violation then null;end;end$$;

do $$begin begin perform public.save_vehicle_configuration('c3400000-0000-4000-9000-000000000001',1,'{}');raise exception 'FAIL cross owner revision';exception when raise_exception then if sqlerrm='FAIL cross owner revision'then raise;end if;end;end$$;
do $$begin begin insert into public.component_observations(vehicle_id,mode)values('c3400000-0000-4000-9000-000000000001','loose');raise exception 'FAIL cross owner scan';exception when foreign_key_violation then null;end;end$$;
reset role;
select set_config('request.jwt.claims','{"sub":"c3400000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
set local role authenticated;
select public.save_vehicle_configuration('c3400000-0000-4000-9000-000000000001',1,'{"engine":"c3400000-0000-4000-8000-000000000011"}');
update public.guide_progress set operation_ids=(select array_agg(o->>'id')from public.repair_operation_plans p,jsonb_array_elements(p.content->'operations')o where p.id='m50-coolant-pump-r1'),completed_steps=array[0,1,2,3,4]where id='c3400000-0000-4000-8000-000000000031';
select public.complete_interactive_repair('c3400000-0000-4000-8000-000000000031',(select content_version from public.guide_progress where id='c3400000-0000-4000-8000-000000000031'),'Synthetic repair verification: cold-level, temperature and leak checks recorded.');
select pg_temp.scanner_assert((select count(*)=1 from public.service_records),'completion saved to existing service history');
select pg_temp.scanner_assert((select count(*)=1 from public.owner_journal_entries),'completion created a private journal');
select pg_temp.scanner_assert((select count(*)=0 from public.garage_journal_entries),'journal was not automatically published');
select pg_temp.scanner_assert((select count(*)=1 from public.completed_repair_runs),'exact run retained');
select public.start_next_interactive_repair('c3400000-0000-4000-8000-000000000031',(select content_version from public.guide_progress where id='c3400000-0000-4000-8000-000000000031'));
select pg_temp.scanner_assert((select cardinality(operation_ids)=0 and service_record_id is null from public.guide_progress where id='c3400000-0000-4000-8000-000000000031'),'new run resets only progress');
select pg_temp.scanner_assert((select count(*)=1 from public.completed_repair_runs),'earlier repair history preserved');
delete from public.component_observations where id='c3400000-0000-4000-8000-000000000021';
select pg_temp.scanner_assert((select count(*)=0 from public.scanner_corrections),'scan deletion cascades corrections');
select pg_temp.scanner_assert((select scan_id is null from public.completed_repair_runs limit 1),'deleted scan unlinked safely');
delete from public.owned_vehicles where id='c3400000-0000-4000-9000-000000000001';
select pg_temp.scanner_assert((select count(*)=0 from public.vehicle_configuration_revisions),'car deletion cascades configuration snapshots');
select pg_temp.scanner_assert((select count(*)=0 from public.completed_repair_runs),'car deletion cascades private repair history');
reset role;
set local role anon;
select pg_temp.scanner_assert((select count(*)=1 from public.repair_operation_plans),'public source plan available');
do $$begin begin perform public.scanner_correction_queue();raise exception 'FAIL anonymous review';exception when insufficient_privilege then null;end;end$$;
reset role;
rollback;
